<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Repositories;
use PDO; use PHPUnit\Framework\TestCase; use Sentinel\Core\Config; use Sentinel\Core\Database; use Sentinel\Core\RuntimeContext; use Sentinel\Repositories\DeviceSessionRepository;
final class DeviceSessionRepositoryTest extends TestCase { public function testSessionsHideForeignCompanyRows():void{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));$db->execute('CREATE TABLE device_sessions (device_session_id INTEGER,company_id INTEGER,device_id INTEGER,device_assignment_id INTEGER,employee_id INTEGER,employee_assignment_id INTEGER,shift_assignment_id INTEGER,site_id INTEGER,session_status TEXT,started_at TEXT,ended_at TEXT,last_seen_at TEXT,created_at TEXT,updated_at TEXT)');$db->execute("INSERT INTO device_sessions VALUES (1,101,1,NULL,7,NULL,NULL,NULL,'ACTIVE','2026-01-01',NULL,NULL,NULL,NULL),(2,202,2,NULL,8,NULL,NULL,NULL,'ACTIVE','2026-01-01',NULL,NULL,NULL,NULL)");$context=new RuntimeContext();$context->setTenantId(101);$repository=new DeviceSessionRepository($db,$context);self::assertCount(1,$repository->listForCompany());self::assertNull($repository->findByIdForCompany('2'));} }